prompt --application/shared_components/plugins/template_component/amc_next_kanban
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(704850467680925822)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_KANBAN'
,p_display_name=>'Next Kanban'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<article class="amc-NKanban-card">',
'  <p class="amc-NKanban-where">#COLUMN_LABEL#</p>',
'  <p class="amc-NKanban-flags"><span class="amc-NKanban-prio"><span class="amc-NKanban-prioCode" aria-hidden="true">{case PRIORITY/}{when critical/}P1{when high/}P2{when low/}P4{otherwise/}P3{endcase/}</span><span class="amc-NKanban-prioText">{case PRIORITY/}{when critical/}Urgent{when high/}High{when low/}Low{otherwise/}Medium{endcase/}</span></span>{case STATE/}{when success/}<span class="amc-NKanban-state">Done</span>{when warning/}<span class="amc-NKanban-state">At risk</span>{when danger/}<span class="amc-NKanban-state">Blocked</span>{when info/}<span class="amc-NKanban-state">Waiting on others</span>{otherwise/}{endcase/}</p>',
'  <h4 class="amc-NKanban-title">{if ?LINK_URL/}<a class="amc-NKanban-link" href="#LINK_URL#">#TITLE#</a>{else/}#TITLE#{endif/}</h4>',
'  {if ?DESCRIPTION/}<p class="amc-NKanban-desc">#DESCRIPTION#</p>{endif/}',
'  {if ?TAGS/}<p class="amc-NKanban-tags">#TAGS#</p>{endif/}',
'  <div class="amc-NKanban-foot">{if ?ASSIGNEE/}<span class="amc-NKanban-who"><span class="amc-NKanban-avatar" aria-hidden="true">{if ?INITIALS/}#INITIALS#{else/}<span class="fa fa-user"></span>{endif/}</span><span class="amc-NKanban-person">#ASSIGNEE#</span></span>{endif/}{if ?DUE_DATE/}<time class="amc-NKanban-due" datetime="#DUE_DATE#">#DUE_DATE#</time>{endif/}</div>',
'</article>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-NKanban amc-NKanban--#STYLE#" data-view="#STYLE#" data-move="#ALLOW_MOVE#" data-card-item="#CARD_ITEM#" data-from-item="#FROM_ITEM#" data-to-item="#TO_ITEM#" data-index-item="#INDEX_ITEM#">',
'  <span class="amc-NKanban-i18n" hidden data-count-limit="%0 of %1" data-count-sr="%0 cards, limit %1" data-count-one="%0 card" data-count-other="%0 cards" data-at-limit="At limit" data-over-limit="Over limit by %0" data-empty="No cards yet. Drag a card here." data-empty-ro="No cards" data-move="Move %0" data-move-help="Press Space to pick up the card, arrow keys to move it, Space to drop it and Escape to cancel." data-picked="Picked up %0 in %1, position %2 of %3. Use the arrow keys to move it." data-moved="%0 is in %1, position %2 of %3." data-dropped="%0 moved to %1, position %2 of %3." data-cancelled="Move cancelled. %0 is back in %1." data-over-note="%0 is now over its limit by %1." data-sorted="Cards in this board are ordered by due date." data-overdue="Overdue" data-today="Due today" data-bucket-overdue="Overdue" data-bucket-today="Today" data-bucket-week="This week" data-bucket-later="Later" data-bucket-none="No due date" data-columns="Board columns" data-due="Due %0"></span>',
'  <ol class="amc-NKanban-source">#APEX$ROWS#</ol>',
'</div>'))
,p_report_row_template=>'<li class="amc-NKanban-item amc-NKanban-item--{case STATE/}{when success/}success{when warning/}warning{when danger/}danger{when info/}info{otherwise/}neutral{endcase/} amc-NKanban-item--{case PRIORITY/}{when critical/}critical{when high/}high{when low/}low{otherwise/}medium{endcase/}{if ?CARD_ID/}{else/}{if ?TITLE/}{else/} amc-NKanban-item--column{endif/}{endif/}" data-id="#CARD_ID#" data-col="#COLUMN_KEY#" data-col-label="#COLUMN_LABEL#" data-limit="#COLUMN_LIMIT#" data-due="#DUE_DATE#">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-kanban.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-kanban.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'One query row per card, already ordered by column and then by position (order by column_seq, card_seq). Map Card ID, Column Key, Column Label and Title; Column Limit (a number, the same on every row of the column) turns on the work-in-progress warning. To show an empty column, return one row for it with Card ID and Title empty. Due Date is ISO text, TO_CHAR(due_on, ''YYYY-MM-DD''). Priority accepts critical, high, medium or low; State accepts success, warning, danger, info or neutral; Tags is a | separated list. When a card is moved the region fires the custom event amc:kanban-move with detail id, from, to, index (0-based position in the target column) and fromIndex, and first sets the page items named in Card Item, From Item, To Item and Index Item, so a Dynamic Action on that custom event can run a PL/SQL process that saves the move and then refreshes the region. Without JavaScript the rows show as a plain list.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(769412413922608638)
,p_plugin_id=>wwv_flow_imp.id(704850467680925822)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'calmLanes'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Design of the board; the direction is given in brackets as motion, depth, bold or smart. calmLanes [smart]: flat tinted lanes with quiet borderless cards and limit slots under each column name; the lanes stack when the region is narrow. opsBoard [bold]: a dense wallboard with large column counts, one-line cards and a solid priority code P1 to P4 (tags are not shown), and a column that goes over its limit turns red. stickyWall [depth]: paper notes tinted by priority, slightly turned, that lift off the wall while they are moved. dueTimeline [motion]: cards inside each column are ordered and grouped by Due Date into Overdue, Today, This week, Later and No date, and overdue dates pulse gently; moving up and down is off because the order comes from the date. compactList [smart]: one column at a time behind tabs with counts, for phones and narrow side regions; drop a card on a tab to move it there.'
);
